// queries.js - Database query functions with connection pooling and timing

const mysql = require('mysql2');
const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'appdb',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

const promisePool = pool.promise();

/**
 * Get a user by ID with SQL injection prevention
 * @param {number} id - User ID
 * @returns {Promise<Object|null>}
 */
async function getUserById(id) {
  const start = Date.now();
  const sql = 'SELECT id, name, email FROM users WHERE id = ?';
  try {
    const [rows] = await promisePool.execute(sql, [parseInt(id)]);
    const duration = Date.now() - start;
    console.log(`Query: ${sql} | Params: [${id}] | Time: ${duration}ms`);
    return rows[0] || null;
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`Query failed: ${sql} | Time: ${duration}ms | Error: ${error.message}`);
    throw error;
  }
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users to return
 * @param {number} offset - Offset for pagination
 * @returns {Promise<Array>}
 */
async function getAllUsers(limit = 10, offset = 0) {
  const start = Date.now();
  const sql = 'SELECT id, name, email FROM users LIMIT ? OFFSET ?';
  try {
    const [rows] = await promisePool.execute(sql, [parseInt(limit), parseInt(offset)]);
    const duration = Date.now() - start;
    console.log(`Query: ${sql} | Params: [${limit}, ${offset}] | Time: ${duration}ms`);
    return rows;
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`Query failed: ${sql} | Time: ${duration}ms | Error: ${error.message}`);
    throw error;
  }
}

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @returns {Promise<Array>}
 */
async function searchUsers(query) {
  const start = Date.now();
  // Using parameterized query with LIKE - prevents SQL injection
n  const searchPattern = `%${query.toString().replace(/[%_]/g, '')}%`;
  const sql = 'SELECT id, name, email FROM users WHERE name LIKE ? OR email LIKE ?';
  try {
    const [rows] = await promisePool.execute(sql, [searchPattern, searchPattern]);
    const duration = Date.now() - start;
    console.log(`Query: ${sql} | Params: [${searchPattern}] | Time: ${duration}ms`);
    return rows;
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`Query failed: ${sql} | Time: ${duration}ms | Error: ${error.message}`);
    throw error;
  }
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers
};

