// queries.js
// Database query functions with connection pooling and timing

const mysql = require('mysql2/promise');

// Create connection pool
const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'test',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

/**
 * Execute a query with timing and logging
 * @param {string} sql - SQL query string
 * @param {Array} params - Query parameters
 * @param {string} queryName - Name of the query for logging
 * @returns {Promise} Query result
 */
async function timedQuery(sql, params, queryName) {
  const start = Date.now();
  try {
    const [results] = await pool.execute(sql, params);
    const duration = Date.now() - start;
    console.log(`Query ${queryName} executed in ${duration}ms`);
    return results;
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`Query ${queryName} failed after ${duration}ms:`, error.message);
    throw error;
  }
}

/**
 * Get user by ID
 * @param {number} id - User ID
 * @returns {Promise} User object or null if not found
 */
async function getUserById(id) {
  // Input validation
  const userId = parseInt(id, 10);
  if (isNaN(userId) || userId <= 0) {
    throw new Error('Invalid user ID');
  }

  return timedQuery(
    'SELECT id, name, email FROM users WHERE id = ?',
    [userId],
    'getUserById'
  );
}

/**
 * Get all users with pagination
 * @param {number} limit - Maximum number of users to return
 * @param {number} offset - Number of users to skip
 * @returns {Promise} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  // Input validation and sanitization
  let queryLimit = parseInt(limit, 10);
  let queryOffset = parseInt(offset, 10);

  // Set reasonable limits
  if (isNaN(queryLimit) || queryLimit < 1) queryLimit = 10;
  if (queryLimit > 100) queryLimit = 100;

  if (isNaN(queryOffset) || queryOffset < 0) queryOffset = 0;

  return timedQuery(
    'SELECT id, name, email FROM users LIMIT ? OFFSET ?',
    [queryLimit, queryOffset],
    'getAllUsers'
  );
}

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @returns {Promise} Array of matching user objects
 */
async function searchUsers(query) {
  // Input validation
  if (!query || typeof query !== 'string' || query.trim().length === 0) {
    throw new Error('Search query cannot be empty');
  }

  const searchQuery = `%${query.trim()}%`;

  return timedQuery(
    'SELECT id, name, email FROM users WHERE name LIKE ? OR email LIKE ?',
    [searchQuery, searchQuery],
    'searchUsers'
  );
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for graceful shutdown if needed
  pool
};

