// Database query functions with connection pooling and logging
const { Pool } = require('pg');

// Configuration from environment variables
const pool = new Pool({
  user: process.env.DB_USER || 'postgres',
  host: process.env.DB_HOST || 'localhost',
  database: process.env.DB_NAME || 'appdb',
  password: process.env.DB_PASSWORD || 'password',
  port: process.env.DB_PORT || 5432,
  max: 20, // max number of clients in the pool
  idleTimeoutMillis: 30000, // close idle clients after 30 seconds
  connectionTimeoutMillis: 2000, // return an error after 2 seconds if connection could not be established
});

// Helper function to execute queries with timing and error logging
async function executeQuery(query, params = []) {
  const start = Date.now();
  const logPrefix = `[DB] ${new Date().toISOString()}`;

  try {
    console.log(`${logPrefix} Executing query: ${query} | Parameters: ${JSON.stringify(params)}`);
    const result = await pool.query(query, params);
    const duration = Date.now() - start;
    console.log(`${logPrefix} Query completed in ${duration}ms`);
    return result;
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`${logPrefix} Query failed after ${duration}ms: ${error.message}`);
    throw error;
  }
}

// Query functions
async function getUserById(id) {
  const query = 'SELECT id, name, email FROM users WHERE id = $1';
  const result = await executeQuery(query, [id]);
  return result.rows[0];
}

async function getAllUsers(limit = 10, offset = 0) {
  const query = 'SELECT id, name, email FROM users LIMIT $1 OFFSET $2';
  const result = await executeQuery(query, [limit, offset]);
  return result.rows;
}

async function searchUsers(query) {
  // Use parameterized query with LIKE and escape any SQL wildcards
  // This prevents SQL injection while allowing pattern matching
  const searchTerm = `%${query.replace(/[%_\\]/g, '\$&')}%`;
  const dbQuery = 'SELECT id, name, email FROM users WHERE name ILIKE $1 OR email ILIKE $1';
  const result = await executeQuery(dbQuery, [searchTerm]);
  return result.rows;
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for graceful shutdown if needed
  pool,
};

