const mysql = require('mysql2/promise');

// Create connection pool with configuration
const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'myapp',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0,
  enableKeepAlive: true,
  keepAliveInitialDelay: 0
});

/**
 * Log query execution time
 * @param {string} queryName - Name of the query for logging
 * @param {number} startTime - Start time timestamp
 */
function logQueryTime(queryName, startTime) {
  const endTime = performance.now();
  const executionTime = endTime - startTime;
  console.log(`Query '${queryName}' executed in ${executionTime.toFixed(2)}ms`);
}

/**
 * Get a user by their ID
 * @param {number} id - User ID
 * @returns {Object|null} User object or null if not found
 */
async function getUserById(id) {
  const startTime = performance.now();

  try {
    // Validate input - ensure ID is a positive integer
    const userId = parseInt(id, 10);
    if (isNaN(userId) || userId <= 0) {
      throw new Error('Invalid user ID');
    }

    const [rows] = await pool.execute(
      'SELECT id, username, email, created_at FROM users WHERE id = ?', 
      [userId]
    );

    logQueryTime('getUserById', startTime);

    return rows.length > 0 ? rows[0] : null;
  } catch (error) {
    logQueryTime('getUserById (error)', startTime);
    console.error('Database error in getUserById:', error);
    throw error;
  }
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users to return
 * @param {number} offset - Offset for pagination
 * @returns {Array} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  const startTime = performance.now();

  try {
    // Validate and sanitize input parameters
    const limitNum = Math.min(Math.max(parseInt(limit, 10) || 10, 1), 100); // Max 100 per request
    const offsetNum = Math.max(parseInt(offset, 10) || 0, 0);

    const [rows] = await pool.execute(
      'SELECT id, username, email, created_at FROM users ORDER BY id LIMIT ? OFFSET ?', 
      [limitNum, offsetNum]
    );

    logQueryTime('getAllUsers', startTime);

    return rows;
  } catch (error) {
    logQueryTime('getAllUsers (error)', startTime);
    console.error('Database error in getAllUsers:', error);
    throw error;
  }
}

/**
 * Search users by query string
 * @param {string} query - Search query
 * @param {number} limit - Maximum results to return
 * @returns {Array} Array of user objects matching the search
 */
async function searchUsers(query, limit = 10) {
  const startTime = performance.now();

  try {
    // Validate and sanitize input
    if (!query || typeof query !== 'string') {
      throw new Error('Search query is required and must be a string');
    }

    // Sanitize query - trim whitespace and limit length
    const searchTerm = query.trim().substring(0, 255);
    if (searchTerm.length === 0) {
      return [];
    }

    // Use parameterized query with LIKE for search
    // Adding wildcards in the parameter, not in the SQL string
    const searchPattern = `%${searchTerm}%`;
    const limitNum = Math.min(Math.max(parseInt(limit, 10) || 10, 1), 50);

    const [rows] = await pool.execute(
      `SELECT id, username, email, created_at 
       FROM users 
       WHERE username LIKE ? OR email LIKE ? 
       ORDER BY id 
       LIMIT ?`, 
      [searchPattern, searchPattern, limitNum]
    );

    logQueryTime('searchUsers', startTime);

    return rows;
  } catch (error) {
    logQueryTime('searchUsers (error)', startTime);
    console.error('Database error in searchUsers:', error);
    throw error;
  }
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for health checks or direct access if needed
  pool
};

