const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'appdb',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

/**
 * Get a user by ID
 * @param {number} id - User ID
 * @returns {Object|null} User object or null if not found
 */
async function getUserById(id) {
  const start = Date.now();
  try {
    const [rows] = await pool.execute(
      'SELECT id, name, email FROM users WHERE id = ?',
      [id]
    );

    if (rows.length === 0) return null;
    return rows[0];
  } finally {
    const duration = Date.now() - start;
    console.log(`getUserById(${id}) executed in ${duration}ms`);
  }
}

/**
 * Get all users with pagination
 * @param {number} limit - Maximum number of users to return
 * @param {number} offset - Number of users to skip
 * @returns {Array} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  const start = Date.now();
  try {
    const [rows] = await pool.execute(
      'SELECT id, name, email FROM users LIMIT ? OFFSET ?',
      [limit, offset]
    );
    return rows;
  } finally {
    const duration = Date.now() - start;
    console.log(`getAllUsers(limit=${limit}, offset=${offset}) executed in ${duration}ms`);
  }
}

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @param {number} limit - Maximum number of results
 * @param {number} offset - Number of results to skip
 * @returns {Array} Array of matching user objects
 */
async function searchUsers(query, limit = 10, offset = 0) {
  const start = Date.now();
  try {
    // Using parameterized queries to prevent SQL injection
    // The LIKE pattern is parameterized, and special characters are escaped by the database driver
    const [rows] = await pool.execute(
      'SELECT id, name, email FROM users WHERE name LIKE ? OR email LIKE ? LIMIT ? OFFSET ?',
      [`%${query}%`, `%${query}%`, limit, offset]
    );
    return rows;
  } finally {
    const duration = Date.now() - start;
    console.log(`searchUsers(query="${query}", limit=${limit}, offset=${offset}) executed in ${duration}ms`);
  }
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers
};

