// Create connection pool
const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'app_db',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

/**
 * Get a user by ID
 * @param {number} id - User ID
 * @returns {Object|null} User object or null if not found
 */
async function getUserById(id) {
  const start = Date.now();
  try {
    const [rows] = await pool.execute(
      'SELECT id, name, email FROM users WHERE id = ?',
      [id]
    );

    if (rows.length === 0) {
      return null;
    }

    console.log(`getUserById query took ${Date.now() - start}ms`);
    return rows[0];
  } catch (error) {
    console.error('Error in getUserById:', error);
    throw error;
  }
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users to return
 * @param {number} offset - Offset for pagination
 * @returns {Array} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  const start = Date.now();
  try {
    // Ensure limit and offset are numbers to prevent injection
    const parsedLimit = Math.min(Math.abs(parseInt(limit, 10)) || 10, 100); // Max 100 per page
    const parsedOffset = Math.max(0, parseInt(offset, 10) || 0);

    const [rows] = await pool.execute(
      'SELECT id, name, email FROM users LIMIT ? OFFSET ?',
      [parsedLimit, parsedOffset]
    );

    console.log(`getAllUsers query took ${Date.now() - start}ms`);
    return rows;
  } catch (error) {
    console.error('Error in getAllUsers:', error);
    throw error;
  }
}

/**
 * Search users by query string
 * @param {string} query - Search term
 * @param {number} limit - Number of results to return
 * @param {number} offset - Offset for pagination
 * @returns {Array} Array of user objects
 */
async function searchUsers(query, limit = 10, offset = 0) {
  const start = Date.now();
  try {
    // Ensure query is a string and sanitize
    const searchQuery = (query || '').toString().trim();

    // Prevent injection by validating limit and offset
    const parsedLimit = Math.min(Math.abs(parseInt(limit, 10)) || 10, 100);
    const parsedOffset = Math.max(0, parseInt(offset, 10) || 0);

    // Use parameterized query with LIKE and ESCAPE clause
    // The ? parameter automatically handles escaping
    const [rows] = await pool.execute(
      `SELECT id, name, email 
       FROM users 
       WHERE name LIKE ? OR email LIKE ?
       LIMIT ? OFFSET ?`,
      [%${searchQuery}%, %${searchQuery}%, parsedLimit, parsedOffset]
    );

    console.log(`searchUsers query took ${Date.now() - start}ms`);
    return rows;
  } catch (error) {
    console.error('Error in searchUsers:', error);
    throw error;
  }
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for health checks or other operations
  pool
};

