// queries.js - Database query functions with connection pooling and timing

const mysql = require('mysql2');
const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'test',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0,
});

const promisePool = pool.promise();

// Helper to log query execution time
const timedQuery = async (query, params, operationName) => {
  const start = Date.now();
  try {
    const [results] = await promisePool.execute(query, params);
    const duration = Date.now() - start;
    console.log(`${operationName} query executed in ${duration}ms`);
    return results;
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`${operationName} query failed after ${duration}ms:`, error.message);
    throw error;
  }
};

/**
 * Get a single user by ID
 * @param {number} id - User ID
 * @returns {Object|null} User object or null if not found
 */
const getUserById = async (id) => {
  const query = 'SELECT id, name, email FROM users WHERE id = ?';
  const results = await timedQuery(query, [id], 'getUserById');
  return results[0] || null;
};

/**
 * Get all users with pagination
 * @param {number} limit - Max number of users to return
 * @param {number} offset - Number of users to skip
 * @returns {Array} Array of user objects
 */
const getAllUsers = async (limit = 10, offset = 0) => {
  // Using parameterized queries - LIMIT and OFFSET must be inserted via JS
  // since mysql2 doesn't parameterize them in prepared statements
  const query = `SELECT id, name, email FROM users LIMIT ? OFFSET ?`;
  return await timedQuery(query, [parseInt(limit), parseInt(offset)], 'getAllUsers');
};

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @param {number} limit - Max number of results
 * @param {number} offset - Number of results to skip
 * @returns {Array} Array of user objects matching the search
 */
const searchUsers = async (query, limit = 10, offset = 0) => {
  if (!query || query.trim().length === 0) {
    return getAllUsers(limit, offset);
  }

  const searchTerm = `%${query.trim()}%`;
  const searchQuery = `SELECT id, name, email FROM users WHERE name LIKE ? OR email LIKE ? LIMIT ? OFFSET ?`;
  return await timedQuery(
    searchQuery,
    [searchTerm, searchTerm, parseInt(limit), parseInt(offset)], 
    'searchUsers'
  );
};

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for graceful shutdown if needed
  pool,
};

