const mysql = require('mysql2/promise');

// Create connection pool
const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'test',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

/**
 * Execute a query with timing and error logging
 * @param {string} sql - SQL query string
 * @param {Array} params - Query parameters
 * @param {string} queryName - Name of the query for logging
 * @returns {Promise} Query result
 */
async function executeQuery(sql, params = [], queryName = 'Unknown query') {
  const startTime = Date.now();

  try {
    const [rows, fields] = await pool.execute(sql, params);
    const duration = Date.now() - startTime;

    console.log(`Query '${queryName}' executed successfully in ${duration}ms`);

    return rows;
  } catch (error) {
    const duration = Date.now() - startTime;
    console.error(`Query '${queryName}' failed after ${duration}ms:`, error.message);
    throw error; // Re-throw the error for the calling code to handle
  }
}

/**
 * Get a user by their ID
 * @param {number} id - User ID
 * @returns {Promise<Object|null>} User object or null if not found
 */
async function getUserById(id) {
  const sql = 'SELECT id, name, email FROM users WHERE id = ?';
  const params = [id];

  const users = await executeQuery(sql, params, 'getUserById');
  return users.length > 0 ? users[0] : null;
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users to return
 * @param {number} offset - Number of users to skip
 * @returns {Promise<Array>} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  // Validate parameters to prevent abuse
  limit = Math.min(Math.abs(parseInt(limit)), 100); // Max 100 per page
  offset = Math.max(0, parseInt(offset));

  const sql = 'SELECT id, name, email FROM users LIMIT ? OFFSET ?';
  const params = [limit, offset];

  return await executeQuery(sql, params, 'getAllUsers');
}

/**
 * Search for users by name or email
 * @param {string} query - Search term
 * @param {number} limit - Maximum number of results
 * @returns {Promise<Array>} Array of matching user objects
 */
async function searchUsers(query, limit = 10) {
  // Validate and sanitize input
  if (!query || typeof query !== 'string') {
    throw new Error('Search query must be a non-empty string');
  }

  // Sanitize query to prevent potential issues
  const sanitizedQuery = query.trim().substring(0, 255);

  // Use parameterized query with LIKE for search
  // Using CONCAT to build the pattern in SQL for safety
  const sql = `SELECT id, name, email 
               FROM users 
               WHERE name LIKE CONCAT('%', ?, '%') 
                  OR email LIKE CONCAT('%', ?, '%') 
               LIMIT ?`;

  // Use the same query for both name and email search
  const params = [sanitizedQuery, sanitizedQuery, Math.min(limit, 50)];

  return await executeQuery(sql, params, 'searchUsers');
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for direct access if needed (e.g., for transactions)
  pool
};

