/**
 * Database queries module for user operations
 * Uses parameterized queries to prevent SQL injection
 * Includes connection pooling and query timing logs
 */

const mysql = require('mysql2/promise');

// Create connection pool
const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'myapp',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

/**
 * Execute a query with timing logs and error handling
 * @param {string} sql - SQL query string
 * @param {Array} params - Parameters for the query
 * @returns {Promise} Query result
 */
async function executeQuery(sql, params = []) {
  const startTime = Date.now();

  try {
    const [results, fields] = await pool.execute(sql, params);
    const duration = Date.now() - startTime;
    console.log(`Query executed in ${duration}ms: ${sql}`);

    return results;
  } catch (error) {
    const duration = Date.now() - startTime;
    console.error(`Query failed after ${duration}ms: ${sql}`);
    console.error('Error:', error.message);
    throw error;
  }
}

/**
 * Get a user by their ID
 * @param {number} id - User ID
 * @returns {Object|null} User object or null if not found
 */
async function getUserById(id) {
  // Input validation
  const userId = parseInt(id, 10);
  if (isNaN(userId) || userId <= 0) {
    throw new Error('Invalid user ID');
  }

  const sql = 'SELECT id, username, email, created_at, updated_at FROM users WHERE id = ?';
  const params = [userId];

  const results = await executeQuery(sql, params);
  return results[0] || null;
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users to return (default: 10)
 * @param {number} offset - Number of users to skip (default: 0)
 * @returns {Array} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  // Input validation and sanitization
  const validLimit = Math.min(Math.max(parseInt(limit, 10) || 10, 1), 100);
  const validOffset = Math.max(parseInt(offset, 10) || 0, 0);

  const sql = `SELECT id, username, email, created_at, updated_at 
               FROM users 
               ORDER BY id 
               LIMIT ? OFFSET ?`;
  const params = [validLimit, validOffset];

  return await executeQuery(sql, params);
}

/**
 * Search users by query string
 * @param {string} query - Search term for username or email
 * @param {number} limit - Maximum results to return
 * @returns {Array} Array of matching user objects
 */
async function searchUsers(query, limit = 10) {
  // Input validation and sanitization
  if (!query || typeof query !== 'string') {
    throw new Error('Search query is required and must be a string');
  }

  // Sanitize query by trimming whitespace
  const searchTerm = query.trim();

  // Prevent empty search
  if (searchTerm.length === 0) {
    return [];
  }

  // Limit results
  const validLimit = Math.min(Math.max(parseInt(limit, 10) || 10, 1), 100);

  // Use parameterized query with LIKE operator
  // The % wildcards are not part of the parameter but added in the SQL
  const sql = `SELECT id, username, email, created_at, updated_at 
               FROM users 
               WHERE username LIKE ? OR email LIKE ?
               ORDER BY username 
               LIMIT ?`;

  // Add wildcards to the search term as parameters
  const searchPattern = `%${searchTerm}%`;
  const params = [searchPattern, searchPattern, validLimit];

  return await executeQuery(sql, params);
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for connection management if needed
  pool
};

