  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'test',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

const promisePool = pool.promise();

/**
 * Get a user by ID
 * @param {number} id - User ID
 * @returns {Promise<Object>} User object
 */
async function getUserById(id) {
  const start = Date.now();
  try {
    const [rows] = await promisePool.execute(
      'SELECT id, name, email, created_at FROM users WHERE id = ?',
      [id]
    );
    const duration = Date.now() - start;
    console.log(`getUserById(${id}) executed in ${duration}ms`);

    if (rows.length === 0) {
      return null;
    }

    return rows[0];
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`getUserById(${id}) failed after ${duration}ms:`, error.message);
    throw error;
  }
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users to return
 * @param {number} offset - Starting position
 * @returns {Promise<Array>} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  const start = Date.now();
  try {
    // Ensure limit and offset are numbers and within reasonable bounds
    const safeLimit = Math.min(Math.max(parseInt(limit) || 10, 1), 100);
    const safeOffset = Math.max(parseInt(offset) || 0, 0);

    const [rows] = await promisePool.execute(
      'SELECT id, name, email, created_at FROM users LIMIT ? OFFSET ?',
      [safeLimit, safeOffset]
    );

    const duration = Date.now() - start;
    console.log(`getAllUsers(limit=${safeLimit}, offset=${safeOffset}) executed in ${duration}ms`);

    return rows;
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`getAllUsers(limit=${limit}, offset=${offset}) failed after ${duration}ms:`, error.message);
    throw error;
  }
}

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @param {number} limit - Maximum number of results
 * @returns {Promise<Array>} Array of matching user objects
 */
async function searchUsers(query, limit = 10) {
  const start = Date.now();
  try {
    // Ensure query is a string and limit is a number
    const safeQuery = String(query || '').trim();
    const safeLimit = Math.min(Math.max(parseInt(limit) || 10, 1), 100);

    // If query is empty, return empty array
    if (!safeQuery) {
      const duration = Date.now() - start;
      console.log(`searchUsers(query="${safeQuery}") returned empty due to empty query in ${duration}ms`);
      return [];
    }

    // Use parameterized query with LIKE - the connection pool handles escaping
    const [rows] = await promisePool.execute(
      `SELECT id, name, email, created_at 
       FROM users 
       WHERE name LIKE ? OR email LIKE ? 
       LIMIT ?`,
      [`%${safeQuery}%`, `%${safeQuery}%`, safeLimit]
    );

    const duration = Date.now() - start;
    console.log(`searchUsers(query="${safeQuery}", limit=${safeLimit}) executed in ${duration}ms`);

    return rows;
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`searchUsers(query="${query}", limit=${limit}) failed after ${duration}ms:`, error.message);
    throw error;
  }
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers
};

